#if swift(>=5.8)
@_documentation(visibility: private)
#endif
fileprivate struct FfiConverterSequenceTypeLunarDay: FfiConverterRustBuffer {
    typealias SwiftType = [LunarDay]

    public static func write(_ value: [LunarDay], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeLunarDay.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [LunarDay] {
        let len: Int32 = try readInt(&buf)
        var seq = [LunarDay]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeLunarDay.read(from: &buf))
        }
        return seq
    }
}
